import React, { useState, useEffect } from 'react';
import { Chart } from 'react-google-charts';
import axios from 'axios';
import './Visualization.css';

function Visualization() {
  const [columns, setColumns] = useState([]);
  const [selectedX, setSelectedX] = useState('');
  const [selectedY, setSelectedY] = useState('');
  const [chartType, setChartType] = useState('ScatterChart');
  const [data, setData] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [darkMode, setDarkMode] = useState(false);

  // Fetch columns on mount
  useEffect(() => {
    const fetchColumns = async () => {
      try {
        const response = await axios.get('http://localhost:8000/data/columns');
        if (response.data.columns && response.data.columns.length >= 2) {
          setColumns(response.data.columns);
          setSelectedX(response.data.columns[0]);
          setSelectedY(response.data.columns[1]);
          setError('');
        } else {
          setError('No columns available for visualization');
        }
      } catch (err) {
        setError('Failed to load column information');
        console.error(err);
      }
    };
    fetchColumns();
  }, []);

  // Generate chart data
  const generateChart = async () => {
    if (!selectedX || !selectedY) {
      setError('Please select both X and Y axes');
      setData([]);
      return;
    }
    setIsLoading(true);
    setError('');
    try {
      const response = await axios.get('http://localhost:8000/data/sample', {
        params: { x: selectedX, y: selectedY, limit: 100 },
      });
      if (!response.data || response.data.length === 0) {
        setError('No data available for selected columns');
        setData([]);
        setIsLoading(false);
        return;
      }
      const chartData = [
        [selectedX, selectedY],
        ...response.data.map(item => [item[selectedX], item[selectedY]]),
      ];
      setData(chartData);
      setError('');
    } catch (err) {
      setError('Failed to generate chart');
      setData([]);
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (selectedX && selectedY) {
      generateChart();
    }
  }, [selectedX, selectedY]);

  // Toggle dark mode and store preference
  const toggleDarkMode = () => {
    setDarkMode(prev => {
      const newMode = !prev;
      if (newMode) document.documentElement.classList.add('dark');
      else document.documentElement.classList.remove('dark');
      return newMode;
    });
  };

  // Initialize dark mode based on user system preference on mount
  useEffect(() => {
    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
    if (prefersDark) {
      setDarkMode(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  return (
    <div className="visualization-container">
      <header className="vis-header">
        <h2>Data Visualization</h2>
        <button
          className="toggle-theme-btn"
          onClick={toggleDarkMode}
          aria-label="Toggle dark mode"
        >
          {darkMode ? '🌞 Light Mode' : '🌙 Dark Mode'}
        </button>
      </header>

      <div className="controls">
        <div className="control-group">
          <label htmlFor="xAxisSelect">X-Axis:</label>
          <select
            id="xAxisSelect"
            value={selectedX}
            onChange={e => setSelectedX(e.target.value)}
            disabled={isLoading}
          >
            <option value="">Select column</option>
            {columns.map(col => (
              <option key={col} value={col}>
                {col}
              </option>
            ))}
          </select>
        </div>

        <div className="control-group">
          <label htmlFor="yAxisSelect">Y-Axis:</label>
          <select
            id="yAxisSelect"
            value={selectedY}
            onChange={e => setSelectedY(e.target.value)}
            disabled={isLoading}
          >
            <option value="">Select column</option>
            {columns.map(col => (
              <option key={col} value={col}>
                {col}
              </option>
            ))}
          </select>
        </div>

        <div className="control-group">
          <label htmlFor="chartTypeSelect">Chart Type:</label>
          <select
            id="chartTypeSelect"
            value={chartType}
            onChange={e => setChartType(e.target.value)}
            disabled={isLoading}
          >
            <option value="ScatterChart">Scatter Chart</option>
            <option value="LineChart">Line Chart</option>
            <option value="BarChart">Bar Chart</option>
            <option value="Histogram">Histogram</option>
          </select>
        </div>
      </div>

      {error && <div className="error-message">{error}</div>}

      <div className="chart-container">
        {isLoading ? (
          <div className="loading">Loading chart data...</div>
        ) : data && Array.isArray(data) && data.length > 1 ? (
          <Chart
            chartType={chartType}
            width="100%"
            height="400px"
            data={data}
            options={{
              title: `${selectedY} vs ${selectedX}`,
              hAxis: { title: selectedX },
              vAxis: { title: selectedY },
              legend: { position: 'none' },
              chartArea: { width: '80%', height: '70%' },
              backgroundColor: 'transparent',
              titleTextStyle: { color: 'var(--text-primary)' },
              hAxisTextStyle: { color: 'var(--text-secondary)' },
              vAxisTextStyle: { color: 'var(--text-secondary)' },
              tooltip: { textStyle: { color: 'var(--text-primary)' } },
            }}
          />
        ) : (
          <div className="no-data">
            {columns.length > 0
              ? 'Select columns to generate chart'
              : 'Loading columns...'}
          </div>
        )}
      </div>
    </div>
  );
}

export default Visualization;
